import sys
from collections import Counter

def countStrings(S):
    n = len(S)
    if n == 2:
        return 1
    count = 0
    last = [-1] * 26
    for i in range(n):
        for j in range(ord(S[i]) + 1, ord('z') + 1):
            if last[j - ord('a')] != -1:
                count += 1
        last[ord(S[i]) - ord('a')] = i
    return count

def main():
    S = sys.stdin.read().strip()
    print(countStrings(S))

if __name__ == "__main__":
    main()
